contents.plugin.json:
{
  "$schema": "https://agent-plugins.org/schemas/1.0.0/plugin.schema.json",
  "name": "nd-developer-critic",
  "version": "1.0.1",
  "description": "Nameless Dhamma Developer Critic launcher.",
  "author": {
    "name": "Nameless Dhamma"
  },
  "repository": "https://github.com/namelessdhamma/nameless-dhamma-vault",
  "keywords": [
    "nameless-dhamma",
    "launcher",
    "engineering",
    "testing",
    "critic"
  ],
  "extensions": {
    "com.openai": {
      "interface": {
        "displayName": "ND Developer Critic",
        "shortDescription": "Mandatory closure Child through True Developer",
        "longDescription": "Mandatory final adversarial review/testing Child for substantive True Developer results.",
        "developerName": "Nameless Dhamma",
        "category": "Developer Tools",
        "defaultPrompt": [
          "Use ND Developer Critic for this task."
        ]
      }
    }
  }
}
